    seen = [[False] * w for _ in range(h)]
    dirs4 = ((1, 0), (-1, 0), (0, 1), (0, -1))
    components = {}

    # Find monochromatic 4-connected components and their bounding boxes.
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in dirs4:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components.setdefault(color, []).append(
                (len(cells), min(y for y, x in cells), max(y for y, x in cells),
                 min(x for y, x in cells), max(x for y, x in cells)))

    # Isolated colored specks are corruptions. Restore them from an enclosing
    # same-color rectangle when present, otherwise from their local neighborhood.
    for color, comps in components.items():
        for size, r0, r1, c0, c1 in comps:
            if size != 1:
                continue
            r, c = r0, c0
            votes = []
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == dx == 0:
                        continue
                    y, x = r + dy, c + dx
                    if 0 <= y < h and 0 <= x < w and grid[y][x] != color:
                        votes.append(grid[y][x])
            # Look for a substantial same-color component whose bounding box
            # contains this point (a one-cell blemish inside a filled rectangle).
            enclosing = []
            for other, other_comps in components.items():
                if other == color:
                    continue
                for n, y0, y1, x0, x1 in other_comps:
                    if n >= 2 and y0 <= r <= y1 and x0 <= c <= x1:
                        enclosing.append((n, other))
            if enclosing:
                # Prefer the largest matching component; this is the rectangle
                # whose interior the speck interrupts.
                out[r][c] = max(enclosing)[1]
            elif votes:
                counts = Counter(votes)
                best = max(counts.values())
                winners = [v for v, n in counts.items() if n == best]
                out[r][c] = global_bg if global_bg in winners else winners[0]
            else:
                out[r][c] = global_bg
    return out


